import { commands as generated } from "./bindings";
import type { ConnectionConfig, GenerationTask, QuerySource, SavePlacement, Target } from "./types";

/** What Settings saves for one provider (`save_settings`). `apiKey: null` keeps the saved key. */
export interface ProviderChoice {
  provider: string;
  typingModel: string;
  expertModel: string;
  baseUrl: string;
  apiKey: string | null;
  workspaceId: string;
}

/**
 * The Tauri commands registered in src-tauri/src/lib.rs, typed from the Rust signatures
 * (`./bindings`, generated by `pnpm gen:types`). Most are the generated wrappers as they are;
 * the ones below take a `Target` or an object where the UI finds that clearer.
 */
export const commands = {
  ...generated,

  /** `config` may be a team connection's (its `team` details are ignored). */
  saveConnection: (
    config: ConnectionConfig,
    password: string | null,
    placement: SavePlacement | null = null,
  ) => generated.saveConnection(config, password, placement),
  serverDatabases: (config: ConnectionConfig, password: string | null) =>
    generated.serverDatabases(config, password),
  testConnection: (config: ConnectionConfig, password: string | null) =>
    generated.testConnection(config, password),
  openDatabase: (t: Target) => generated.openDatabase(t.connectionId, t.database),
  refreshSchema: (t: Target) => generated.refreshSchema(t.connectionId, t.database),

  /**
   * `runId` lets `cancelQuery` stop the query while it runs. On a team connection, `source` and
   * `question` go with the query to the team server's audit log.
   */
  runQuery: (
    t: Target,
    sql: string,
    allowWrite: boolean,
    runId?: string,
    source?: QuerySource,
    question?: string,
  ) =>
    generated.runQuery(
      t.connectionId,
      t.database,
      sql,
      allowWrite,
      runId ?? null,
      source ?? null,
      question ?? null,
    ),

  /**
   * Asks the AI for SQL; the answer streams back as `ai://` events (see `subscribeToAi`).
   * - `slot` scopes cancellation: a new request replaces the previous one in the same slot (editor tab).
   * - `focusTables`: qualified table names the person picked; drafts see only those and their neighbours.
   * - `skill`: the slug of a saved skill whose instruction goes with the request.
   */
  generateSql: (
    t: Target,
    question: string,
    reqId: number,
    slot: string,
    task: GenerationTask,
    focusTables: string[],
    skill: string | null,
  ) =>
    generated.generateSql(
      t.connectionId,
      t.database,
      question,
      reqId,
      slot,
      task,
      focusTables,
      skill,
    ),

  /**
   * Starts an agent run in `slot` (the tab), stopping the one there; progress arrives as
   * `agent://event`s (see `subscribeToAgent`). `followUp` continues the tab's last run.
   * `auto`: Auto mode, which doesn't stop for the plan or before each send.
   */
  startAgent: (
    t: Target,
    question: string,
    runId: string,
    slot: string,
    focusTables: string[],
    skill: string | null,
    followUp: boolean,
    auto: boolean,
  ) =>
    generated.startAgent(
      t.connectionId,
      t.database,
      question,
      runId,
      slot,
      focusTables,
      skill,
      followUp,
      auto,
    ),
  listNotes: (t: Target) => generated.listNotes(t.connectionId, t.database),
  /** Reads the schema again, reviews the notes against it and runs every check. */
  checkNotes: (t: Target) => generated.checkNotes(t.connectionId, t.database),
  /** Suggests a note on a team connection for the team's knowledge owners to approve; resolves with what to tell the person. */
  suggestNote: (connectionId: string, text: string, check: string) =>
    generated.suggestNote(connectionId, text, check.trim() || null),

  mcpActivity: (limit?: number) => generated.mcpActivity(limit ?? null),
  /** Your own queries, newest first; for one connection when given. */
  myActivity: (connectionId: string | null, limit?: number) =>
    generated.myActivity(connectionId, limit ?? null),

  /** Adds a git repository once git can read it. `token`: optional, read-only, kept in the keychain. */
  addKnowledgeRepo: (
    connectionId: string,
    repo: {
      url: string;
      branch: string;
      subdir: string;
      token: string | null;
      tokenUser: string | null;
    },
  ) =>
    generated.addKnowledgeRepo(
      connectionId,
      repo.url,
      repo.branch,
      repo.subdir,
      repo.token,
      repo.tokenUser,
    ),

  /** Saves the choices for one provider and makes it the one that writes SQL. */
  saveSettings: (c: ProviderChoice) =>
    generated.saveSettings(
      c.provider,
      c.typingModel,
      c.expertModel,
      c.baseUrl,
      c.apiKey,
      c.workspaceId,
    ),
};
